import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.stereotype.Service;

@Service
public class OrderService {
  private final Counter ordersCreated;

  public OrderService(MeterRegistry registry) {
    // ✅ NEW: a counter with tags (channel) for slicing in Prometheus
    this.ordersCreated = Counter.builder("orders.created")
        .description("Total orders created")
        .tag("channel", "web")
        .register(registry); // ✅ NEW: registered into the MeterRegistry
  }

  public Order create(OrderRequest req) {
    Order order = doCreate(req);
    ordersCreated.increment(); // ✅ NEW: exact increment, concurrency-safe
    return order;
  }
}

// Prometheus: GET /actuator/prometheus
//   orders_created_total{channel="web"} 42.0
// Grafana queries it directly — no log parsing.

